using System.Security.Claims;using DadoHome.Api.Auth;using DadoHome.Api.Data;using Microsoft.EntityFrameworkCore;
namespace DadoHome.Api.Inventory;
public static class ReturnEndpoints{public static IEndpointRouteBuilder MapReturnEndpoints(this IEndpointRouteBuilder app){app.MapGet("/api/admin/orders/{id:guid}",async(Guid id,DadoDbContext db)=>{var order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==id);if(order is null)return Results.NotFound();var items=await db.OrderItems.Where(x=>x.OrderId==id).ToListAsync();return Results.Ok(new{order,items});}).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.OrderManager,Roles.Finance,Roles.Support));app.MapPost("/api/admin/orders/{id:guid}/returns",async(Guid id,StockReturnRequest r,ClaimsPrincipal user,ReturnService service)=>{var actor=user.FindFirstValue(ClaimTypes.NameIdentifier)??user.FindFirstValue("sub")??"staff";var result=await service.ReturnToStock(id,r,actor);return result.Ok?Results.Ok(result.Return):Results.BadRequest(new{error=result.Error});}).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.OrderManager));app.MapGet("/api/admin/product-returns",async(DadoDbContext db)=>await db.ProductReturns.OrderByDescending(x=>x.CreatedAt).Take(200).ToListAsync()).RequireAuthorization(p=>p.RequireRole(Roles.Administrator,Roles.OrderManager,Roles.Finance,Roles.Support));return app;}}
